CREATE TABLE qhr_violation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,source_type varchar(40) NOT NULL,source_ref uuid,reported_by uuid,description text,status varchar(40) NOT NULL DEFAULT 'reported',verification_result varchar(40),redirected_to_employee_id uuid,serious boolean NOT NULL DEFAULT false,serious_reasons jsonb NOT NULL DEFAULT '[]',brand_damage boolean NOT NULL DEFAULT false,financial_damage boolean NOT NULL DEFAULT false,workflow_instance_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_violation_cases_org_idx ON qhr_violation_cases(org_id,employee_id,status);
CREATE TABLE qhr_violation_explanations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,case_id uuid NOT NULL REFERENCES qhr_violation_cases(id),employee_id uuid NOT NULL,content text NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_violation_explanations_org_idx ON qhr_violation_explanations(org_id,case_id);
CREATE TABLE qhr_violation_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,case_id uuid NOT NULL REFERENCES qhr_violation_cases(id),employee_id uuid NOT NULL,manager_id uuid,description text,legal_basis text,revision int NOT NULL DEFAULT 0,employee_signed boolean NOT NULL DEFAULT false,manager_signed boolean NOT NULL DEFAULT false,status varchar(40) NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_violation_records_org_idx ON qhr_violation_records(org_id,case_id,status);
CREATE TABLE qhr_disciplinary_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,case_id uuid NOT NULL REFERENCES qhr_violation_cases(id),record_id uuid REFERENCES qhr_violation_records(id),employee_id uuid NOT NULL,council_members jsonb NOT NULL DEFAULT '[]',union_rep uuid,minutes text,held_at timestamptz,status varchar(40) NOT NULL DEFAULT 'scheduled',workflow_instance_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_disciplinary_meetings_org_idx ON qhr_disciplinary_meetings(org_id,case_id,status);
CREATE TABLE qhr_disciplinary_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,meeting_id uuid REFERENCES qhr_disciplinary_meetings(id),case_id uuid NOT NULL REFERENCES qhr_violation_cases(id),employee_id uuid NOT NULL,decision_type varchar(40) NOT NULL,decision_no varchar(80),signed_by uuid,issued_at timestamptz,status varchar(40) NOT NULL DEFAULT 'draft',effective_from date,termination_flow_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_disciplinary_decisions_org_idx ON qhr_disciplinary_decisions(org_id,employee_id,status);
CREATE TABLE qhr_violation_appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,decision_id uuid NOT NULL REFERENCES qhr_disciplinary_decisions(id),employee_id uuid NOT NULL,content text NOT NULL,status varchar(40) NOT NULL DEFAULT 'submitted',suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_violation_appeals_org_idx ON qhr_violation_appeals(org_id,decision_id,status);
CREATE TABLE qhr_resignation_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,reason text,expected_last_day date,status varchar(40) NOT NULL DEFAULT 'pending_manager',request_type varchar(40) NOT NULL DEFAULT 'resignation',source_decision_id uuid,rejection_reason text,workflow_instance_id uuid,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_resignation_requests_org_idx ON qhr_resignation_requests(org_id,employee_id,status);
CREATE TABLE qhr_exit_interviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,resignation_id uuid NOT NULL REFERENCES qhr_resignation_requests(id),employee_id uuid NOT NULL,interviewer_id uuid NOT NULL,content_encrypted text NOT NULL,visibility varchar(60) NOT NULL DEFAULT 'director_interviewer_only',conducted_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_exit_interviews_org_idx ON qhr_exit_interviews(org_id,resignation_id,interviewer_id);
CREATE TABLE qhr_handover_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,resignation_id uuid NOT NULL REFERENCES qhr_resignation_requests(id),employee_id uuid NOT NULL,handover_type varchar(40) NOT NULL,giver_id uuid,receiver_id uuid,items jsonb NOT NULL DEFAULT '[]',signed_at timestamptz,status varchar(40) NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_handover_records_org_idx ON qhr_handover_records(org_id,resignation_id,handover_type,status);
CREATE TABLE qhr_offboarding_checklists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,resignation_id uuid NOT NULL REFERENCES qhr_resignation_requests(id),employee_id uuid NOT NULL,item varchar(120) NOT NULL,status varchar(40) NOT NULL DEFAULT 'pending',done_by uuid,done_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_offboarding_checklists_org_idx ON qhr_offboarding_checklists(org_id,resignation_id,status);
CREATE TABLE qhr_final_settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,resignation_id uuid NOT NULL REFERENCES qhr_resignation_requests(id),employee_id uuid NOT NULL,insurance_book_returned boolean NOT NULL DEFAULT false,documents_returned boolean NOT NULL DEFAULT false,payroll_settled_by uuid,amount numeric(20,2) NOT NULL DEFAULT 0,settled_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_final_settlements_org_idx ON qhr_final_settlements(org_id,resignation_id);
CREATE TABLE qhr_audit_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,period varchar(40),scope jsonb NOT NULL DEFAULT '[]',region text,audit_team jsonb NOT NULL DEFAULT '[]',status varchar(40) NOT NULL DEFAULT 'pending_board',workflow_instance_id uuid,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_audit_plans_org_idx ON qhr_audit_plans(org_id,status);
CREATE TABLE qhr_audit_visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,plan_id uuid NOT NULL REFERENCES qhr_audit_plans(id),target_branch_id uuid,trip_request_id uuid,checklist_results jsonb NOT NULL DEFAULT '{}',started_at timestamptz,ended_at timestamptz,status varchar(40) NOT NULL DEFAULT 'planned',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_audit_visits_org_idx ON qhr_audit_visits(org_id,plan_id,status);
CREATE TABLE qhr_audit_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,visit_id uuid NOT NULL REFERENCES qhr_audit_visits(id),finding_type varchar(80),severity varchar(40) NOT NULL DEFAULT 'minor',employee_id uuid,description text,violation_case_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_audit_findings_org_idx ON qhr_audit_findings(org_id,visit_id,severity);
CREATE TABLE qhr_corrective_action_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,finding_id uuid NOT NULL REFERENCES qhr_audit_findings(id),assigned_branch_id uuid,assigned_to uuid,deadline timestamptz NOT NULL,evidence_url text,status varchar(40) NOT NULL DEFAULT 'open',overdue_notified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_corrective_action_requests_org_idx ON qhr_corrective_action_requests(org_id,status,deadline);
